import {
  execSync
} from "node:child_process";
import fs from "node:fs";

const ZERO_SHA = "0000000000000000000000000000000000000000";

function parseSemver(version) {
  if (typeof version !== "string") return null;
  const clean = version.trim().replace(/^v/, "").split("-")[0];
  const parts = clean.split(".").map((n) => Number.parseInt(n, 10));
  if (parts.length < 2 || parts.some((n) => Number.isNaN(n) || n < 0)) return null;
  while (parts.length < 3) parts.push(0);
  return parts.slice(0, 3);
}

function isGreaterVersion(nextVer, prevVer) {
  const next = parseSemver(nextVer);
  const prev = parseSemver(prevVer);
  if (!next || !prev) return false;
  for (let i = 0; i < 3; i++) {
    if (next[i] > prev[i]) return true;
    if (next[i] < prev[i]) return false;
  }
  return false;
}

function readJsonAtRef(ref, filePath) {
  try {
    const content = execSync(git show $ {
      ref
    }: $ {
      filePath
    }, {
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
    });
    return JSON.parse(content);
  } catch {
    return null;
  }
}

function writeOutput(key, value) {
  if (process.env.GITHUB_OUTPUT) {
    fs.appendFileSync(process.env.GITHUB_OUTPUT, $ {
        key
      } = $ {
        value
      }\
      n);
  }
  console.log($ {
    key
  } = $ {
    value
  });
}

const eventName = process.env.GITHUB_EVENT_NAME || "push";
const beforeRef = process.argv[2] || process.env.BEFORE_SHA || "";
const currentRef = process.argv[3] || "HEAD";

const currentAppJson = readJsonAtRef(currentRef, "app.json") || JSON.parse(fs.readFileSync("app.json", "utf8"));
const newVersion = currentAppJson?.expo?.version || "";

let oldVersion = "";
let shouldRelease = false;
let reason = "";

if (eventName === "workflow_dispatch") {
  shouldRelease = true;
  reason = Manual release
  for $ {
    newVersion
  };
} else if (!beforeRef || beforeRef === ZERO_SHA) {
  reason = "No previous commit to compare against.";
} else {
  oldVersion = readJsonAtRef(beforeRef, "app.json")?.expo?.version || "";
  if (!oldVersion) {
    reason = Could not read expo.version at $ {
      beforeRef
    }.;
  } else if (isGreaterVersion(newVersion, oldVersion)) {
    shouldRelease = true;
    reason = Version bumped: $ {
      oldVersion
    } - > $ {
      newVersion
    };
  } else {
    reason = Version did not increase($ {
      oldVersion
    } - > $ {
      newVersion
    }).Skipping.;
  }
}

writeOutput("should_release", shouldRelease ? "true" : "false");
writeOutput("old_version", oldVersion || "none");
writeOutput("new_version", newVersion || "none");
writeOutput("reason", reason);

{
  "cli" : {"appVersionSource" : "remote"},
            "build"
      : {"production" : {"autoIncrement" : true, "android" : {"buildType" : "app-bundle"}}},
        "submit" : {
    "production" : {
      "ios" : {"ascAppId" : "YOUR_ASC_APP_ID"}, "android" : {
        "track" : "production", "releaseStatus" : "draft"
      }
    }
  }
}
